module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);
// Define state parameters
parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
parameter S5 = 3'b101;
// Define state register
reg [2:0] ST_cr, ST_nr;
// Combinational logic for next state generation
always @* begin
    case (ST_cr)
        S0: begin
            if (IN == 1) ST_nr = S1;
            else ST_nr = S0;
        end
        S1: begin
            if (IN == 1) ST_nr = S1;
            else ST_nr = S2;
        end
        S2: begin
            if (IN == 1) ST_nr = S1;
            else ST_nr = S3;
        end
        S3: begin
            if (IN == 1) ST_nr = S4;
            else ST_nr = S0;
        end
        S4: begin
            if (IN == 1) ST_nr = S5;
            else ST_nr = S2;
        end
        S5: begin
            if (IN == 1) ST_nr = S1;
            else ST_nr = S2;
        end
        default: ST_nr = S0;
    endcase
end
// Sequential logic for state register update
always @(posedge CLK or posedge RST) begin
    if (RST) begin
        ST_cr <= S0;
    end else begin
        ST_cr <= ST_nr;
    end
end
// Combinational logic for output generation
always @* begin
    if (RST) MATCH = 0;
    else if (ST_cr == S4 && IN == 1) MATCH = 1;
    else MATCH = 0;
end
endmodule
